SELECT grade FROM Highschooler WHERE ID IN (
    SELECT student_id FROM Friend GROUP BY student_id HAVING COUNT(*) >= 4
);

SELECT T1.name FROM Highschooler AS T1 JOIN (
    SELECT friend_id FROM Friend GROUP BY friend_id ORDER BY COUNT(*) DESC LIMIT 1
) AS T2 ON T1.ID = T2.friend_id;

SELECT T1.Abbreviation, T1.Country FROM airlines AS T1 JOIN (
    SELECT Airline, COUNT(*) as flight_count FROM flights GROUP BY Airline ORDER BY flight_count LIMIT 1
) AS T2 ON T1.uid = T2.Airline;

SELECT Template_Type_Code FROM Templates WHERE Template_ID = 
(SELECT Document_ID FROM Documents WHERE Document_Name = 'Data Base') AND Template_Type_Code IN (
SELECT DISTINCT Template_Type_Code FROM Documents);

SELECT T.Template_ID, R.Template_Type_Code FROM (
    SELECT Template_ID, COUNT(*) AS doc_count 
    FROM Documents 
    GROUP BY Template_ID 
) AS T JOIN Templates AS R ON T.Template_ID = R.Template_ID WHERE T.doc_count = (
    SELECT MAX(doc_count) 
    FROM (
        SELECT Template_ID, COUNT(*) AS doc_count 
        FROM Documents 
        GROUP BY Template_ID 
    )
);

SELECT MAX(winner_rank) FROM (
  SELECT winner_rank FROM matches 
  UNION ALL
  SELECT loser_rank FROM matches
) AS combined_matches;

SELECT T1.ranking_date, COUNT(T2.player_id) as total_tours 
FROM rankings AS T1 JOIN players AS T2 ON T1.player_id = T2.player_id 
GROUP BY T1.ranking_date;

SELECT T1.country_code FROM players AS T1 JOIN (
  SELECT loser_country_code AS country_code FROM matches GROUP BY loser_country_code ORDER BY COUNT(*) DESC LIMIT 1
) AS T2 ON T1.country_code = T2.country_code;

SELECT winner_name, winner_rank FROM players WHERE player_id IN (
  SELECT winner_id FROM matches ORDER BY winner_age ASC LIMIT 3
);

SELECT T1.first_name, T1.birth_date FROM players AS T1 JOIN (
  SELECT loser_name FROM matches WHERE loser_country_code = 'USA'
UNION ALL
  SELECT winner_name FROM matches WHERE winner_country_code = 'USA'
) AS T2 ON T1.player_id = T2.winner_id OR T1.player_id = T2.loser_id;

SELECT p.winner_name FROM players p JOIN (
  SELECT w.player_id, MAX(r.ranking_points) AS max_points 
  FROM rankings r JOIN players w ON r.player_id = w.player_id 
  WHERE r.tours = 'Australian Open' 
  GROUP BY w.player_id
) t ON p.player_id = t.player_id;

SELECT T1.first_name, T1.country_code FROM players AS T1 JOIN (
  SELECT winner_id FROM matches WHERE tournament_name IN ('WTA Championships', 'Australian Open')
) AS T2 ON T1.player_id = T2.winner_id AND T1.tournament_name = 'WTA Championships' INTERSECT SELECT T1.first_name, T1.country_code FROM players AS T1 JOIN (
  SELECT winner_id FROM matches WHERE tournament_name IN ('WTA Championships', 'Australian Open')
) AS T2 ON T1.player_id = T2.winner_id AND T1.tournament_name = 'Australian Open';

SELECT T1.country_code, T1.first_name FROM players AS T1 JOIN (
  SELECT winner_id FROM matches WHERE tournament_name IN ('WTA Championships', 'Australian Open')
) AS T2 ON T1.player_id = T2.winner_id AND T1.tournament_name IN ('WTA Championships', 'Australian Open');

SELECT T1.first_name, T1.country_code, T1.birth_date FROM players AS T1 JOIN (
    SELECT winner_id, MAX(winner_rank_points) as max_points 
    FROM rankings 
    GROUP BY winner_id
) AS T2 ON T1.player_id = T2.winner_id;

SELECT COUNT(DISTINCT T1.student_enrolment_id) AS max_transcripts, T1.student_enrolment_id FROM Student_Enrolment CTE 
